def solution(tree):
    # Recursive walk: the obvious first version. Correct, but every folder
    # level is one Python call frame, so a very deep tree raises RecursionError.
    out = []
    def walk(folder, prefix):
        for name in folder:
            node = folder[name]
            if isinstance(node, dict):
                walk(node, prefix + name + '/')
            elif 'TODO' in node:
                out.append(prefix + name)
    walk(tree, '')
    return sorted(out)
